<script setup lang="ts">
import {ref,computed} from 'vue';import {useStatus} from '../lib/useStatus';import {date} from '../lib/format';import type {Run} from '../types';import Icon from '../components/Icon.vue';import Notice from '../components/Notice.vue';import EmptyState from '../components/EmptyState.vue';import Badge from '../components/Badge.vue';import RunDetails from '../components/RunDetails.vue'
const {status,error,loading,load}=useStatus();const filter=ref('all'),selected=ref<Run>();const rows=computed(()=>[...(status.value?.history||[])].reverse().filter(r=>filter.value==='all'||r.status===filter.value))
</script><template><div class="admin-heading"><div><span class="eyebrow">SYNC HISTORY</span><h1>同步记录</h1><p>查看 IP 获取、DNS 预览与同步结果。</p></div><button class="btn" :disabled="loading" @click="load"><Icon name="refresh" :size="17"/>刷新记录</button></div><Notice :message="error"/><Notice v-if="status?.pending_operations.length" :message="`有 ${status.pending_operations.length} 条写入尚未核对。只有重新读取到对应 DNS 记录后才会解除，不会自动重发写请求。`"/><section class="card"><div class="card-heading split"><h2>运行历史 <span class="count-label">{{status?.history.length??'—'}}</span></h2><span class="muted">最近 30 轮</span></div><div class="filter-bar"><label class="inline">运行结果<select v-model="filter" aria-label="筛选运行结果"><option value="all">全部结果</option><option value="ok">成功</option><option value="error">失败</option><option value="interrupted">已中断</option></select></label></div><div v-if="rows.length" class="table-scroll"><table><thead><tr><th>运行时间</th><th>模式</th><th>状态</th><th>待更新</th><th>已核验</th><th>操作</th></tr></thead><tbody><tr v-for="(run,index) in rows" :key="index"><td>{{date(run.started_at)}}</td><td><span v-if="run.kind==='source'">IP 获取</span><Badge v-else :value="run.mode"/></td><td><Badge :value="run.status"/></td><td>{{run.planned}}</td><td>{{run.changed}}</td><td><button class="btn small" @click="selected=run">查看详情</button></td></tr></tbody></table></div><EmptyState v-else icon="clock" :title="loading?'正在读取记录…':'暂无匹配记录'" text="运行完成后会保留该轮结果。"/></section><RunDetails :selected="selected" @close="selected=undefined"/></template>
